// The compiled snes9x chip units (snes9x-chips.json, generated by
// scripts/recompile-gen/snes9x-chips.mjs): snes9x's own dsp1-4.cpp,
// seta010/011/018.cpp, obc1.cpp, srtc.cpp, msu1.cpp and bsx.cpp built for
// wasm32 and printed as WAT. A unit's memory (its globals, tables, the
// C stack) sits at a base the cart's layout chooses; the generator wrote
// every address inside it as @{offset}.
//
// Plain JS ESM + JSDoc.

import { readFileSync } from "node:fs";

let CHIPS = null;
function units() {
  if (!CHIPS) CHIPS = JSON.parse(readFileSync(new URL("./snes9x-chips.json", import.meta.url), "utf8")).units;
  return CHIPS;
}

/**
 * @param {string} name  unit name (dsp, seta, st018, obc1, srtc, msu1, bsx)
 */
export function chipUnit(name) {
  const u = units()[name];
  if (!u) throw new Error(`snes chips: no compiled unit ${name} in snes9x-chips.json`);
  return u;
}

/** Bytes of memory the unit needs at its base (data, bss, C stack). */
export function unitSize(name) { return chipUnit(name).size; }

/**
 * The WAT function name of a unit export (e.g. romdev_dsp_get).
 * @param {string} name
 * @param {string} fn
 */
export function unitFn(name, fn) {
  const f = chipUnit(name).exports[fn];
  if (!f) throw new Error(`snes chips: unit ${name} exports no ${fn}`);
  return f;
}

/** The unit's start function (it zeroes its .bss), or null. */
export function unitStart(name) { return chipUnit(name).start; }

/**
 * The whole unit as module fields, placed at `base`.
 * @param {string} name
 * @param {number} base  linear address of the unit's memory (16-byte aligned)
 */
export function unitWat(name, base) {
  const u = chipUnit(name);
  const place = (t) => t.replace(/@\{(-?\d+)\}/g, (_, n) => String(base + Number(n)));
  const parts = [`  ;; ---- snes9x chip unit '${name}' (snes9x-chips.json), memory at 0x${base.toString(16)}, ${u.size} bytes`];
  if (u.types) parts.push(u.types);
  if (u.table) parts.push(u.table);
  if (u.globals) parts.push(place(u.globals));
  for (const d of u.data) {
    const bytes = Buffer.from(d.hex, "hex");
    for (const r of d.relocs) bytes.writeUInt32LE((base + r.rel) >>> 0, r.at);
    let s = "";
    for (const v of bytes) s += "\\" + (v < 16 ? "0" : "") + v.toString(16);
    parts.push(`  (data (i32.const ${base + d.off}) "${s}")`);
  }
  parts.push(place(u.funcs));
  return parts.join("\n");
}
